    public class MECompanysController : BaseBusinessController
    {
        public MECompanysController()
        {
            dal = new DALBaseProvider("MECompanys", typeof(MECompanysInfo));
        }

        /// <summary>
        /// Get all company
        /// </summary>
        /// <returns>List of all company</returns>
        public List<MECompanysInfo> GetAllCompany()
        {
            List<MECompanysInfo> companyList = new List<MECompanysInfo>();
            MECompanysController objCompanysController = new MECompanysController();
            DataSet ds = objCompanysController.GetAllObjects();
            if (ds.Tables[0].Rows.Count > 0)
            {
                foreach (DataRow dr in ds.Tables[0].Rows)
                {
                    MECompanysInfo objCompanysInfo = new MECompanysInfo();
                    objCompanysInfo = (MECompanysInfo)objCompanysController.GetObjectFromDataRow(dr);
                    companyList.Add(objCompanysInfo);
                }
            }
            return companyList;
        }

        public DataSet GetCompanysForLookupEdit()
        {
            return dal.GetDataSet("MECompanys_GetCompanysForLookupEdit");
        }
    }
    #endregion
}